-- Athena saved query (Product_B2C_Intl)
-- ID: 756df98c-5375-4cd8-b6d1-a77c02e64d1c
-- Name: Cohort_deals route ids clicked - Syed
-- Source: Syed Athena Saved Queries export
-- Prefer dataplatform MCP / Iceberg for runs; adjust only date params.
-- Default country: IND when applicable.

/* Route click concentration for Cohort Deals BoostUI analysis Change date_params per day (2026-04-01 .. 2026-04-29). Grain: doi x exp_variant x user_type */ WITH date_params AS ( SELECT TIMESTAMP '2026-04-25 18:30:00' AS start_time, TIMESTAMP '2026-04-29 18:30:00' AS end_time ), srp AS ( SELECT CAST(DATE_TRUNC('day', at_timezone(__time, 'Asia/Kolkata')) AS DATE) AS doi, mri_session_id, route_id, UPPER(user_type) AS user_type, CASE WHEN channel_exp_info IS NULL THEN 'null' WHEN contains(channel_exp_info, 'COHORT_DEALS_SRP_AB:V0') THEN 'V0' WHEN contains(channel_exp_info, 'COHORT_DEALS_SRP_AB:V1') THEN 'V1' WHEN contains(channel_exp_info, 'COHORT_DEALS_SRP_AB:V2') THEN 'V2' WHEN contains(channel_exp_info, 'COHORT_DEALS_SRP_AB:V3') THEN 'V3' WHEN contains(channel_exp_info, 'COHORT_DEALS_SRP_AB:V4') THEN 'V4' ELSE 'others' END AS exp_variant, MAX(CASE WHEN cohort_type = 'BOOSTUI' THEN 1 ELSE 0 END) AS boostui_seen FROM user_interaction.search_route_details s CROSS JOIN date_params d WHERE s.__time >= d.start_time AND s.__time < d.end_time AND channel = 'MOBILE_APP' AND os = 'iOS' AND tp_channel = 'INVALID' AND country = 'IND' AND DATE_DIFF('day', DATE(DATE_ADD('MINUTE', 330, __time)), doj) = 0 GROUP BY 1, 2, 3, 4, 5 ), session_attrs AS ( SELECT doi, mri_session_id, exp_variant, user_type, MAX(boostui_seen) AS boostui_seen FROM srp WHERE exp_variant IN ('V0', 'V1', 'V2') GROUP BY 1, 2, 3, 4 ), red_deal_rids AS ( SELECT DISTINCT exp_variant, route_id FROM srp WHERE boostui_seen = 1 AND exp_variant IN ('V0', 'V1', 'V2') ), sl AS ( SELECT CAST(DATE_TRUNC('day', at_timezone(__time, 'Asia/Kolkata')) AS DATE) AS doi, CASE WHEN channel_exp_info IS NULL THEN 'null' WHEN contains(channel_exp_info, 'COHORT_DEALS_SRP_AB:V0') THEN 'V0' WHEN contains(channel_exp_info, 'COHORT_DEALS_SRP_AB:V1') THEN 'V1' WHEN contains(channel_exp_info, 'COHORT_DEALS_SRP_AB:V2') THEN 'V2' WHEN contains(channel_exp_info, 'COHORT_DEALS_SRP_AB:V3') THEN 'V3' WHEN contains(channel_exp_info, 'COHORT_DEALS_SRP_AB:V4') THEN 'V4' ELSE 'others' END AS exp_variant, mri_session_id, route_id, mri_uuid, MAX(CASE WHEN user_origin LIKE 'BOOSTUI%' THEN 1 ELSE 0 END) AS sl_entry FROM user_interaction.seat_layout_details s CROSS JOIN date_params d WHERE s.__time >= d.start_time AND s.__time < d.end_time AND os = 'iOS' AND country = 'IND' AND DATE(DATE_ADD('MINUTE', 330, __time)) = CAST(doj AS DATE) GROUP BY 1, 2, 3, 4, 5 ) SELECT sl.doi, sl.exp_variant, COUNT(DISTINCT sl.mri_uuid) overall_clicks, COUNT(DISTINCT sl.mri_session_id) overall_sessions, COUNT(DISTINCT sa.mri_session_id) boosted_sessions, COUNT(DISTINCT CASE WHEN sl.sl_entry = 1 THEN sl.mri_uuid END) AS boost_ui_sl_clicks, COUNT(DISTINCT CASE WHEN sl.sl_entry = 1 THEN sl.mri_session_id END) AS boost_ui_sl_sessions, COUNT(DISTINCT sl.route_id) overall_unique_route_id_clicked, COUNT(DISTINCT CASE WHEN sa.mri_session_id IS NOT NULL THEN sl.route_id END) AS boosted_sessions_all_unique_route_id_clicked, COUNT(DISTINCT rdr.route_id) overall_unique_boosted_route_id_clicked, COUNT(DISTINCT CASE WHEN sa.mri_session_id IS NOT NULL THEN rdr.route_id END) AS boosted_sessions_boosted_route_id_clicked, COUNT(DISTINCT CASE WHEN sl.sl_entry = 1 THEN sl.route_id END) AS unique_route_id_clicked_on_boost_ui, COUNT(DISTINCT CASE WHEN sl.sl_entry = 0 THEN sl.route_id END) AS normal_unique_route_id_clicked FROM sl sl LEFT JOIN session_attrs sa ON sa.mri_session_id = sl.mri_session_id AND boostui_seen = 1 AND sa.exp_variant = sl.exp_variant LEFT JOIN red_deal_rids rdr ON rdr.exp_variant = sl.exp_variant AND rdr.route_id = sl.route_id WHERE sl.exp_variant IN ('V0', 'V1', 'V2') GROUP BY 1, 2 ORDER BY 1, 2
